{
 "driver_archetypes": [
  {
   "id": "car_saval",
   "base_vclass": "passenger",
   "share": 0.9,
   "params": {
    "accel": 1.2,
    "decel": 4.8,
    "tau": 2.5,
    "minGap": 1.1
   },
   "rationale": "Saval et al. 2023, Table 11 (Driver parameter values for Hanoi, column Car, GA-calibrated on Tay Son): max acceleration a = 1.2 m/s2 -> accel, max deceleration b = 4.8 m/s2 -> decel, time headway T = 2.5 s -> tau, safety distance s0 = 1.1 m -> minGap (IDM -> Krauss, literature_transferred). Sec 4: cars always stop at red, so no red-running rule and the jm* attributes stay at the SUMO defaults (never drive at red). One archetype: the paper has one car driver type."
  },
  {
   "id": "car_seeker",
   "base_vclass": "custom2",
   "distribution": "car",
   "share": 0.1,
   "params": {
    "accel": 1.2,
    "decel": 4.8,
    "tau": 2.5,
    "minGap": 1.1
   },
   "rationale": "F2 structure (Viktor 2026-10-27, F2-behaviours fix round 1): car violators (custom2, PLAN 0) drawn from the car distribution, the only cars queue_space_seeking may act on. Params copied from car_saval (Saval et al. 2023 Table 11, literature_transferred), so with every p = 0 they drive exactly like car_saval. Share 0.1 is assumed (no source for the share of space-seeking drivers): small, so the B1 car population stays essentially the Saval one; P1/B2 tune it."
  },
  {
   "id": "moto_saval",
   "base_vclass": "motorcycle",
   "share": 0.9,
   "params": {
    "accel": 1.1,
    "decel": 4.6,
    "tau": 0.8,
    "minGap": 1.9,
    "minGapLat": 0.3
   },
   "rationale": "Saval et al. 2023, Table 11 (column Motorcycle): a = 1.1 m/s2 -> accel, b = 4.6 m/s2 -> decel, T = 0.8 s -> tau, s0 = 1.9 m -> minGap (IDM -> Krauss, literature_transferred). minGapLat: Sec 4 sizes a motorcycle 'lane' as 0.8 m = 0.7 m width + 0.1 m safe spacing, i.e. ~0.1 m lateral gap; 0.1 m is below the lower bound 0.3 m of the space (ruling R15), so the bound 0.3 m is used (transferred and clipped). One archetype: the paper has one motorcycle driver type."
  },
  {
   "id": "moto_seeker",
   "base_vclass": "custom1",
   "distribution": "moto",
   "share": 0.1,
   "params": {
    "accel": 1.1,
    "decel": 4.6,
    "tau": 0.8,
    "minGap": 1.9,
    "minGapLat": 0.3
   },
   "rationale": "F2 structure (Viktor 2026-10-27, F2-behaviours fix round 1): motorcycle violators (custom1, PLAN 0) drawn from the moto distribution, the only riders that may use the custom1-only sidewalk or the right-lane / wrong-lane spaces of queue_space_seeking. Params copied from moto_saval (Saval et al. 2023 Table 11 / Sec 4, literature_transferred), and the same red-running / early-start rules, so with every p = 0 they ride exactly like moto_saval. Share 0.1 is assumed (no source): small, so B1's motorcycle population stays essentially the Saval one; P1/B2 tune it."
  },
  {
   "id": "moto_violator_saval",
   "base_vclass": "custom1",
   "share": 0.9,
   "params": {
    "accel": 1.1,
    "decel": 4.6,
    "tau": 0.8,
    "minGap": 1.9,
    "minGapLat": 0.3,
    "jmTimegapMinor": 1.0
   },
   "rationale": "Illegal left-turning motorcycles (vTypeDistribution moto_violator). The car-following and lateral values are the motorcycle values of Saval et al. 2023 Table 11 / Sec 4, as for moto_saval: they are the same riders. jmTimegapMinor = 1.0 s is the SUMO default and is assumed (the paper has no illegal left turn and no gap acceptance); it is in the structure because it is the early-leaving lever of the box waiters (ruling R15) that P1/B2 tune."
  }
 ],
 "traci_rules": [
  {
   "rule_type": "swarm_red_running",
   "applies_to": [
    "moto_saval",
    "moto_seeker",
    "moto_violator_saval"
   ],
   "params": {
    "p0": 0.5,
    "k": 0.0,
    "p_max": 0.5,
    "dt": 10.0
   },
   "rationale": "Saval et al. 2023, Sec 4 'Description of the model and parameters used': from the Tay Son footage 'the probability of stopping for motorcycles (in the front row) is only 0.5'; 'a motorcycle arriving at a red light will have only a 50% chance to stop'. Transferred as a constant run-the-red probability p0 = p_max = 0.5 for a motorcycle reaching the stop line during red, k = 0 (the paper has no swarm effect). dt = 10 s is assumed and has no effect while k = 0."
  },
  {
   "rule_type": "early_start",
   "applies_to": [
    "moto_saval",
    "moto_seeker",
    "moto_violator_saval"
   ],
   "params": {
    "t_before_green": 5.0,
    "p": 0.1302,
    "v_max": 2.0
   },
   "rationale": "Targets M2/early/moto (observed mean 0.1302 share) by setting p=0.1302. t_before_green = 5 s and v_max = 2 m/s are assumed mid-range values."
  },
  {
   "rule_type": "queue_space_seeking",
   "applies_to": [
    "moto_seeker"
   ],
   "params": {
    "q": 30.0,
    "t_g_s": 0.0,
    "est_noise": 0.0,
    "p_wrong_lane": 0.249,
    "p_right_lane": 0.0,
    "p_sidewalk": 0.751,
    "v_creep": 3.0,
    "merge_zone_m": 15.0
   },
   "rationale": "Targets M8/moto (wrong-lane share of turning vehicles: observed mean 0.249) by setting p_wrong_lane=0.249. Targets M10a/per_cycle (sidewalk motorcycles per cycle: observed mean 0.56 veh/cycle) by increasing p_sidewalk from 0.31 to 0.751 to compensate for the lower share of moto_seeker (0.1 vs previous 0.9+0.1=1.0), ensuring total probability mass matches observations."
  },
  {
   "rule_type": "uturn_bypass",
   "applies_to": [
    "moto_saval",
    "moto_seeker",
    "moto_violator_saval"
   ],
   "params": {
    "p": 0.8,
    "t_wait": 2.0
   },
   "rationale": "Viktor 2026-10-30 (field): most motorcycles behind a standing U-turner squeeze past it or move to the next lane; p = 0.8 and t_wait = 2 s assumed (no count)."
  },
  {
   "rule_type": "uturn_bypass",
   "applies_to": [
    "car_saval",
    "car_seeker"
   ],
   "params": {
    "p": 0.1,
    "t_wait": 2.0
   },
   "rationale": "Viktor 2026-10-30 (field): cars rarely change lane to pass a standing U-turner; p = 0.1 and t_wait = 2 s assumed (no count)."
  }
 ]
}

